const out=path.join(process.cwd(),'dist');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const css=`*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#171717;background:#fff}a{color:inherit}.nav{border-bottom:1px solid #e8e8e8;background:#fff;position:sticky;top:0;z-index:5}.nav-inner{max-width:1100px;margin:auto;padding:16px 20px;display:flex;justify-content:space-between;align-items:center}.brand{font-weight:800;text-decoration:none}.nav-link{text-decoration:none;color:#555}.container{max-width:1100px;margin:auto;padding:0 20px}.hero{padding:55px 20px 30px}.eyebrow,.detail-code,.code{font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#777}h1{font-size:clamp(30px,6vw,52px);line-height:1.05;margin:10px 0 14px}.hero p{max-width:650px;color:#666;font-size:17px}.toolbar{display:flex;gap:12px;align-items:center;margin:10px 0 22px}.search{width:100%;max-width:420px;padding:13px 15px;border:1px solid #ddd;border-radius:12px;font-size:16px}.count{color:#777;font-size:14px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:18px;padding-bottom:60px}.card{display:block;text-decoration:none;border:1px solid #e8e8e8;border-radius:16px;overflow:hidden;background:#fff;transition:transform .15s,box-shadow .15s}.card:hover{transform:translateY(-2px);box-shadow:0 8px 24px #00000012}.image{height:230px;background:#f7f7f7;display:flex;align-items:center;justify-content:center}.image img{width:100%;height:100%;object-fit:contain}.info{padding:16px}.name{font-weight:700;margin-top:6px}.view{margin-top:12px;color:#555;font-size:14px}footer{border-top:1px solid #eee;color:#777;padding:25px 0;font-size:13px}.detail{padding-top:30px;padding-bottom:60px}.back{display:inline-block;text-decoration:none;color:#666;margin-bottom:25px}.detail-layout{display:grid;grid-template-columns:minmax(280px,1fr) minmax(280px,1fr);gap:50px;align-items:start}.detail-image{background:#f7f7f7;border-radius:18px;min-height:400px;display:flex;align-items:center;justify-content:center;overflow:hidden}.detail-image img{width:100%;height:auto;max-height:650px;object-fit:contain}.detail-copy{font-size:17px;line-height:1.65;color:#555}.specs{margin-top:28px;border-top:1px solid #eee}.spec{display:flex;justify-content:space-between;padding:15px 0;border-bottom:1px solid #eee}.spec span{color:#777}@media(max-width:700px){.detail-layout{grid-template-columns:1fr;gap:25px}.detail-image{min-height:300px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.image{height:170px}.info{padding:12px}}`;
function page(title,body,description=''){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="stylesheet" href="/catalog/styles.css"></head><body><header class="nav"><div class="nav-inner"><a class="brand" href="/catalog/">Kajal Enterprises</a><a class="nav-link" href="/catalog/">Catalog</a></div></header>${body}<footer><div class="container">© 2026 Kajal Enterprises · Product Catalog</div></footer></body></html>`}
function detail(p){const url=`https://kajalenterprises.github.io/catalog/${p.code}/`;const schema={'@context':'https://schema.org','@type':'Product',name:p.name,sku:p.code.toUpperCase(),image:[url+'image.jpg'],description:p.description,brand:{'@type':'Brand',name:'Kajal Enterprises'},offers:{'@type':'Offer',url,availability:'https://schema.org/InStock'}};return page(`${p.name} | Kajal Enterprises`, `<main class="detail container"><a class="back" href="/catalog/">← Back to catalog</a><div class="detail-layout"><div class="detail-image"><img src="/catalog/${p.code}/image.jpg" alt="${esc(p.name)}" loading="eager"></div><section><div class="detail-code">PRODUCT CODE · ${p.code.toUpperCase()}</div><h1>${esc(p.name)}</h1><p class="detail-copy">${esc(p.description)}</p><p class="detail-copy">${esc(p.details)}</p><div class="specs"><div class="spec"><span>Product code</span><strong>${p.code.toUpperCase()}</strong></div><div class="spec"><span>Category</span><strong>${esc(p.category)}</strong></div><div class="spec"><span>Availability</span><strong>Available</strong></div></div></section></div></main><script type="application/ld+json">${JSON.stringify(schema)}</script>`,p.description)}
fs.rmSync(out,{recursive:true,force:true});fs.mkdirSync(path.join(out,'catalog'),{recursive:true});
fs.writeFileSync(path.join(out,'catalog','styles.css'),css);
const cards=products.map(p=>`<a class="card" href="/catalog/${p.code}/"><div class="image"><img src="/catalog/${p.code}/image.jpg" alt="${esc(p.name)}" loading="lazy"></div><div class="info"><div class="code">${p.code.toUpperCase()}</div><div class="name">${esc(p.name)}</div><div class="view">View product →</div></div></a>`).join('');
const catBody=`<main><section class="hero container"><div class="eyebrow">Kajal Enterprises</div><h1>Product Catalog</h1><p>Browse our products by product code. Select any product to open its dedicated product page.</p></section><section class="container"><div class="toolbar"><input class="search" id="search" placeholder="Search product code…" autocomplete="off"><div class="count" id="count"></div></div><div class="grid" id="grid">${cards}</div></section></main><script>const g=document.getElementById('grid'),c=document.getElementById('count'),all=[...g.children];function f(){const q=document.getElementById('search').value.toLowerCase();let n=0;all.forEach(x=>{const ok=x.innerText.toLowerCase().includes(q);x.style.display=ok?'block':'none';if(ok)n++});c.textContent=n+' product'+(n===1?'':'s')}document.getElementById('search').addEventListener('input',f);f();</script>`;
fs.writeFileSync(path.join(out,'catalog','index.html'),page('Kajal Enterprises Product Catalog',catBody,'Kajal Enterprises product catalog.'));
for(const p of products){const dir=path.join(out,'catalog',p.code);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),detail(p));fs.writeFileSync(path.join(dir,'image.jpg'),Buffer.from(p.image.split(',')[1],'base64'));}
fs.writeFileSync(path.join(out,'robots.txt'),'User-agent: *\nAllow: /\n\nSitemap: https://kajalenterprises.github.io/sitemap.xml\n');
fs.writeFileSync(path.join(out,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${['catalog',...products.map(p=>`catalog/${p.code}`)].map(x=>`<url><loc>https://kajalenterprises.github.io/${x}/</loc></url>`).join('')}</urlset>`);
fs.writeFileSync(path.join(out,'index.html'),'<meta http-equiv="refresh" content="0; url=/catalog/">');
